<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
require_admin();
$pdo = db(); $error=''; $success=''; $editResult=null;
$subjects=['php','dbms','computer_network','operating_system','computer_graphics'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    $action=$_POST['action']??'';
    try{
        if($action==='save'){
            $id=(int)($_POST['id']??0); $studentId=(int)($_POST['student_id']??0); $marks=[];
            foreach($subjects as $subject){$value=(int)($_POST[$subject]??-1); if($value<0||$value>100) throw new RuntimeException('Each mark must be between 0 and 100.'); $marks[$subject]=$value;}
            if(!$studentId) throw new RuntimeException('Please select a student.');
            $calc=calculate_result(array_values($marks));
            if($id){$sql='update results set student_id=:student_id, php=:php, dbms=:dbms, computer_network=:computer_network, operating_system=:operating_system, computer_graphics=:computer_graphics, total=:total, percentage=:percentage, grade=:grade, status=:status, updated_at=now() where id=:id'; $stmt=$pdo->prepare($sql); $stmt->execute(array_merge(['student_id'=>$studentId],$marks,$calc,['id'=>$id])); $success='Result updated successfully.';}
            else{$sql='insert into results (student_id,php,dbms,computer_network,operating_system,computer_graphics,total,percentage,grade,status) values (:student_id,:php,:dbms,:computer_network,:operating_system,:computer_graphics,:total,:percentage,:grade,:status)'; $stmt=$pdo->prepare($sql); $stmt->execute(array_merge(['student_id'=>$studentId],$marks,$calc)); $success='Result added successfully.';}
        }elseif($action==='delete'){$stmt=$pdo->prepare('delete from results where id=:id');$stmt->execute(['id'=>(int)$_POST['id']]);$success='Result deleted successfully.';}
    }catch(Throwable $e){$error=$e->getCode()==='23505'?'This student already has a result.':$e->getMessage();}
}
if(isset($_GET['edit'])){$stmt=$pdo->prepare('select * from results where id=:id');$stmt->execute(['id'=>(int)$_GET['edit']]);$editResult=$stmt->fetch();}
$students=$pdo->query('select id,name,roll_number from students order by name')->fetchAll();
$search=trim($_GET['q']??'');
if($search!==''){$stmt=$pdo->prepare('select r.*,s.name,s.roll_number from results r join students s on s.id=r.student_id where s.name ilike :q or s.roll_number ilike :q order by r.id desc');$stmt->execute(['q'=>"%{$search}%"]);$results=$stmt->fetchAll();}
else{$results=$pdo->query('select r.*,s.name,s.roll_number from results r join students s on s.id=r.student_id order by r.id desc')->fetchAll();}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Manage Results</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="admin-layout"><aside class="sidebar"><a class="brand" href="../index.php">Result <span>System</span></a><nav><a href="dashboard.php">Dashboard</a><a href="students.php">Students</a><a class="active" href="results.php">Results</a><a href="logout.php">Logout</a></nav></aside><main class="admin-main"><div class="page-heading"><p class="eyebrow">Administration</p><h1>Results</h1><p class="muted">Add, update and manage student marks.</p></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><section class="panel"><div class="panel-head"><div><h2><?= $editResult?'Edit Result':'Add Result' ?></h2><p class="muted">Total, percentage, grade and status are calculated automatically.</p></div><?php if($editResult):?><a class="btn btn-ghost" href="results.php">Cancel</a><?php endif;?></div><?php if(!$students):?><div class="empty-state"><h3>Add a student first</h3><p>Results can only be added for existing students.</p><a class="btn btn-primary" href="students.php">Manage Students</a></div><?php else:?><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($editResult['id']??''))?>"><label>Student<select name="student_id" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=((int)($editResult['student_id']??0)===(int)$s['id'])?'selected':''?>><?=e($s['name'])?> — <?=e($s['roll_number'])?></option><?php endforeach;?></select></label><div class="marks-grid"><?php $labels=['php'=>'PHP','dbms'=>'DBMS','computer_network'=>'Computer Network','operating_system'=>'Operating System','computer_graphics'=>'Computer Graphics'];foreach($labels as $field=>$label):?><label><?=e($label)?><input type="number" min="0" max="100" name="<?=$field?>" required value="<?=e((string)($editResult[$field]??''))?>"></label><?php endforeach;?></div><div class="form-actions"><button class="btn btn-primary" type="submit"><?= $editResult?'Update Result':'Save Result' ?></button></div></form><?php endif;?></section><section class="panel"><div class="panel-head"><h2>Result List</h2><form class="inline-search"><input name="q" value="<?=e($search)?>" placeholder="Search name or roll no"><button class="btn btn-secondary">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Roll No</th><th>Student</th><th>Total</th><th>%</th><th>Grade</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($results as $r):?><tr><td><?=e($r['roll_number'])?></td><td><?=e($r['name'])?></td><td><?=e((string)$r['total'])?> / 500</td><td><?=e((string)$r['percentage'])?>%</td><td><?=e($r['grade'])?></td><td><span class="status-badge <?= $r['status']==='PASS'?'pass':'fail' ?>"><?=e($r['status'])?></span></td><td class="actions"><a class="btn btn-small" href="?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this result?');"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-small danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$results):?><tr><td colspan="7" class="empty-cell">No results found.</td></tr><?php endif;?></tbody></table></div></section></main></div></body></html>
